    63→      queuedDecisions.length > 0
    64→        ? queuedDecisions.shift()
    65→        : "{\"type\":\"final\",\"content\":\"ok\"}"
    66→    const payload = createMockPlannerDecisionResponse(decisionText, String(requests.length))
    67→    res.writeHead(200, { "content-type": "application/json" })
    68→    res.end(JSON.stringify(payload))
