   318→  if (names.has("mcp__cc-official-broker-runner__write_file")) {
   319→    hideBuiltins.add("Write")
   320→  }
   321→  if (names.has("mcp__cc-official-broker-runner__apply_patch")) {
   322→    hideBuiltins.add("Edit")
   323→  }
   324→
   325→  for (const tool of list) {
   326→    const name = String(tool?.name || "")
   327→    if (hideBuiltins.has(name)) {
   328→      continue
   329→    }
   330→    filtered.push(tool)
   331→  }
   332→
   333→  return filtered.length ? filtered : list
   334→}
   335→
   336→function summarizeAnthropicMessages(messages = []) {
   337→  const lines = []
   338→
   339→  for (const message of Array.isArray(messages) ? messages : []) {
   340→    const role = String(message?.role || "user").toUpperCase()
   341→    for (const block of normalizeMessageContent(message?.content)) {
   342→      if (block.type === "text") {
   343→        const text = sanitizeClaudeText(block.text || "", 1600)
   344→        if (text) {
   345→          lines.push(`${role}: ${text}`)
   346→        }
   347→        continue
   348→      }
   349→
   350→      if (block.type === "tool_use") {
   351→        lines.push(
   352→          `${role}_TOOL_USE ${String(block.name || "")}: ${compactText(
   353→            JSON.stringify(block.input || {}),
   354→            1000
   355→          )}`
   356→        )
   357→        continue
   358→      }
   359→
   360→      if (block.type === "tool_result") {
   361→        const text = sanitizeClaudeText(toolResultText(block.content), 1600)
   362→        if (text) {
   363→          lines.push(`${role}_TOOL_RESULT ${String(block.tool_use_id || "")}: ${text}`)
   364→        }
   365→      }
   366→    }
   367→  }
   368→
   369→  return lines.slice(-16).join("\n")
   370→}
   371→
   372→function extractUserAsk(messages = []) {
   373→  if (!Array.isArray(messages) || !messages.length) {
   374→    return ""
   375→  }
   376→
   377→  for (let index = messages.length - 1; index >= 0; index -= 1) {
   378→    const item = messages[index]
   379→    if (!item || item.role !== "user") {
   380→      continue
   381→    }
   382→    const text = normalizeMessageContent(item.content)
   383→      .filter(block => block.type === "text")
   384→      .map(block => sanitizeClaudeText(block.text || "", 2000))
   385→      .filter(Boolean)
   386→      .join("\n\n")
   387→      .trim()
   388→    if (text) {
   389→      return text
   390→    }
   391→  }
   392→
   393→  return ""
   394→}
