   406→
   407→function findLatestUserTextMessageIndex(messages = []) {
   408→  const list = Array.isArray(messages) ? messages : []
   409→  for (let index = list.length - 1; index >= 0; index -= 1) {
   410→    const message = list[index]
   411→    if (!message || message.role !== "user") {
   412→      continue
   413→    }
   414→    const hasText = normalizeMessageContent(message.content).some(
   415→      block => block?.type === "text" && sanitizeClaudeText(block.text || "", 2000)
   416→    )
   417→    if (hasText) {
   418→      return index
   419→    }
   420→  }
   421→  return -1
   422→}
   423→
   424→function latestMessageIsToolResultOnly(messages = []) {
   425→  const list = Array.isArray(messages) ? messages : []
   426→  const last = list[list.length - 1]
   427→  if (!last || last.role !== "user") {
   428→    return false
   429→  }
   430→
   431→  const blocks = normalizeMessageContent(last.content)
   432→  if (!blocks.length) {
   433→    return false
   434→  }
   435→
   436→  let hasToolResult = false
   437→  for (const block of blocks) {
   438→    if (block?.type === "tool_result") {
   439→      hasToolResult = true
   440→      continue
   441→    }
   442→    if (block?.type === "text" && !sanitizeClaudeText(block.text || "", 2000)) {
   443→      continue
   444→    }
   445→    return false
   446→  }
   447→
   448→  return hasToolResult
   449→}
   450→
   451→function buildToolNameByUseId(messages = []) {
   452→  const mapping = new Map()
   453→  for (const message of Array.isArray(messages) ? messages : []) {
   454→    for (const block of normalizeMessageContent(message.content)) {
   455→      if (block?.type !== "tool_use") {
   456→        continue
   457→      }
   458→      const id = String(block.id || "").trim()
   459→      const name = String(block.name || "").trim()
   460→      if (id && name) {
   461→        mapping.set(id, name)
   462→      }
   463→    }
   464→  }
   465→  return mapping
   466→}
   467→
   468→function evaluateToolResultEvidence(messages = [], startIndex = -1, expectedToolNames = []) {
   469→  const list = Array.isArray(messages) ? messages : []
   470→  const expected = new Set((Array.isArray(expectedToolNames) ? expectedToolNames : []).map(name => String(name || "")).filter(Boolean))
   471→  const toolNameByUseId = buildToolNameByUseId(list)
   472→  let totalToolResults = 0
   473→  let matchedToolResults = 0
   474→  let unresolvedToolResults = 0
   475→
   476→  for (let messageIndex = Math.max(0, startIndex + 1); messageIndex < list.length; messageIndex += 1) {
   477→    const message = list[messageIndex] || {}
   478→    for (const block of normalizeMessageContent(message.content)) {
   479→      if (block?.type !== "tool_result") {
   480→        continue
   481→      }
   482→
   483→      totalToolResults += 1
   484→      const toolUseId = String(block.tool_use_id || "").trim()
   485→      const toolName = toolUseId ? toolNameByUseId.get(toolUseId) : ""
   486→      if (!toolName) {
   487→        unresolvedToolResults += 1
   488→        continue
   489→      }
   490→      if (expected.has(toolName)) {
   491→        matchedToolResults += 1
   492→      }
   493→    }
   494→  }
   495→
   496→  return {
   497→    totalToolResults,
   498→    matchedToolResults,
   499→    unresolvedToolResults
   500→  }
   501→}
   502→
   503→function hasSatisfiedLocalExecution(messages = [], latestUserAskIndex = -1, expectedToolNames = []) {
   504→  if (latestUserAskIndex < 0) {
   505→    return false
   506→  }
   507→
   508→  const evidence = evaluateToolResultEvidence(messages, latestUserAskIndex, expectedToolNames)
   509→  if (evidence.matchedToolResults > 0) {
   510→    return true
   511→  }
   512→
   513→  if (!evidence.totalToolResults) {
   514→    return false
   515→  }
   516→
   517→  return evidence.unresolvedToolResults > 0 && latestMessageIsToolResultOnly(messages)
   518→}
