   520→function shouldRequireLocalFileMutationTool(userAsk = "", explicitToolName = "") {
   521→  const ask = String(userAsk || "")
   522→  const explicit = String(explicitToolName || "")
   523→  if (
   524→    explicit === "Write" ||
   525→    explicit === "Edit" ||
   526→    explicit === RUNNER_TOOL.writeFile ||
   527→    explicit === RUNNER_TOOL.applyPatch
   528→  ) {
   529→    return true
   530→  }
   531→
   532→  const patterns = [
   533→    /\b(create|write|append|overwrite)\b.{0,30}\b(file|files)\b/i,
   534→    /\b(edit|modify|update|patch|replace|delete|remove|rename)\b.{0,30}\b(file|files)\b/i,
   535→    /\bapply[_\s-]?patch\b/i,
   536→    /(创建|新建|写入|追加|覆盖).{0,12}(文件|file)/,
   537→    /(修改|编辑|替换|补丁|删除|重命名).{0,12}(文件|file)/
   538→  ]
   539→  return patterns.some(pattern => pattern.test(ask))
   540→}
