   542→function shouldRequireLocalBashTool(userAsk = "", explicitToolName = "") {
   543→  const ask = String(userAsk || "")
   544→  const explicit = String(explicitToolName || "")
   545→  if (explicit === "Bash" || explicit === RUNNER_TOOL.bash) {
