   599→  const mapped = BUILTIN_MUTATION_TO_RUNNER.get(name)
   600→  if (!mapped) {
   601→    return name
   602→  }
   603→
   604→  const availableNames = getAvailableToolNames(availableTools)
   605→  return availableNames.has(mapped) ? mapped : name
