  1027→  for (const message of messages) {
  1028→    const role = String(message?.role || "user")
  1029→    const textParts = []
  1030→
  1031→    const flushTextParts = currentRole => {
  1032→      if (!textParts.length) return
  1033→      items.push({
  1034→        type: "message",
  1035→        role: currentRole,
  1036→        content: [...textParts]
  1037→      })
  1038→      textParts.length = 0
  1039→    }
  1040→
  1041→    for (const block of normalizeMessageContent(message?.content)) {
  1042→      const blockType = block.type
  1043→      if (blockType === "text" || blockType === "image") {
  1044→        const converted = contentBlockToResponses(block, role)
  1045→        if (converted) {
