  1189→function extractChatBlocks(payload = {}) {
  1190→  const blocks = []
  1191→  const choice = payload.choices?.[0] || {}
  1192→  const message = choice.message || {}
  1193→  const content = message.content
  1194→
  1195→  if (typeof content === "string" && content) {
  1196→    blocks.push({
  1197→      type: "text",
  1198→      text: content
  1199→    })
  1200→  } else if (Array.isArray(content)) {
  1201→    for (const item of content) {
  1202→      if (typeof item === "string") {
  1203→        blocks.push({ type: "text", text: item })
  1204→        continue
  1205→      }
  1206→      if (item && typeof item === "object" && item.text) {
  1207→        blocks.push({ type: "text", text: String(item.text) })
  1208→      }
  1209→    }
  1210→  }
  1211→
  1212→  for (const toolCall of message.tool_calls || []) {
