  1315→            id: block.id,
  1316→            name: block.name,
  1317→            input: {}
  1318→          }
  1319→        : {
  1320→            type: "text",
  1321→            text: ""
  1322→          }
  1323→
  1324→    events.push(
  1325→      `event: content_block_start\ndata: ${JSON.stringify({
  1326→        type: "content_block_start",
  1327→        index,
  1328→        content_block: contentBlock
