  1500→export async function startOfficialUpstreamProxy(config, overrides = {}) {
  1501→  if (!config.remoteServiceBaseUrl) {
  1502→    throw new Error("CC_BROKER_REMOTE_SERVICE_BASE_URL is required")
  1503→  }
  1504→  if (!config.remoteServiceBearerToken && !config.remoteServiceApiKey) {
  1505→    throw new Error("remote service auth is required for official proxy")
  1506→  }
  1507→
  1508→  const host = overrides.host || "127.0.0.1"
  1509→  const port = overrides.port || 0
  1510→  const bridgeToken = overrides.bridgeToken || `official-proxy-${randomUUID()}`
  1511→  const state = {
  1512→    sessionId: overrides.sessionId || `official-proxy-${Date.now().toString(36)}`,
  1513→    previousResponseId: String(overrides.previousResponseId || ""),
  1514→    remoteSessionId: String(overrides.remoteSessionId || "")
  1515→  }
  1516→
  1517→  const server = http.createServer(async (req, res) => {
  1518→    const pathname = normalizePath(req.url || "/")
  1519→    const authHeader = String(req.headers.authorization || "")
  1520→    const expected = `Bearer ${bridgeToken}`
  1521→
  1522→    if (authHeader !== expected && pathname !== "/healthz") {
  1523→      writeAnthropicError(res, 401, "invalid bridge auth token", "authentication_error")
  1524→      return
  1525→    }
  1526→
  1527→    if (req.method === "GET" && pathname === "/healthz") {
  1528→      jsonResponse(res, 200, {
  1529→        ok: true,
  1530→        service: "cc-official-broker-official-proxy",
  1531→        session_id: state.sessionId
  1532→      })
  1533→      return
  1534→    }
  1535→
  1536→    if (req.method === "GET" && pathname === "/v1/models") {
  1537→      try {
  1538→        jsonResponse(res, 200, await fetchRemoteModels(config))
  1539→      } catch (error) {
  1540→        writeAnthropicError(res, 500, error instanceof Error ? error.message : String(error))
  1541→      }
  1542→      return
  1543→    }
  1544→
  1545→    if (req.method === "POST" && pathname === "/v1/messages/count_tokens") {
  1546→      try {
  1547→        const body = await readJsonBody(req)
  1548→        jsonResponse(res, 200, {
  1549→          input_tokens: approxTokenCount(body)
  1550→        })
  1551→      } catch (error) {
  1552→        writeAnthropicError(res, 400, error instanceof Error ? error.message : String(error), "invalid_request_error")
  1553→      }
  1554→      return
  1555→    }
  1556→
  1557→    if (req.method === "POST" && pathname === "/v1/messages") {
  1558→      let body = null
  1559→      try {
  1560→        body = await readJsonBody(req)
  1561→      } catch (error) {
  1562→        writeAnthropicError(res, 400, error instanceof Error ? error.message : String(error), "invalid_request_error")
  1563→        return
  1564→      }
  1565→
  1566→      try {
