   715→function tryParseJsonObject(text = "") {
   716→  const raw = String(text || "").trim()
   717→  if (!raw) {
   718→    return null
   719→  }
   720→
   721→  const candidates = [raw]
   722→  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i)
   723→  if (fenced?.[1]) {
   724→    candidates.unshift(fenced[1].trim())
   725→  }
   726→
   727→  const firstBrace = raw.indexOf("{")
   728→  const lastBrace = raw.lastIndexOf("}")
   729→  if (firstBrace >= 0 && lastBrace > firstBrace) {
   730→    candidates.push(raw.slice(firstBrace, lastBrace + 1))
   731→  }
   732→
   733→  for (const candidate of candidates) {
   734→    try {
   735→      const parsed = JSON.parse(candidate)
   736→      if (parsed && typeof parsed === "object") {
   737→        return parsed
   738→      }
   739→    } catch {
   740→      // ignore
   741→    }
   742→  }
   743→
   744→  return null
   745→}
   746→
   747→function decodePlannerJsonStringFragment(fragment = "") {
   748→  const raw = String(fragment || "")
   749→    .replace(/"}?\s*$/, "")
   750→    .trim()
   751→
   752→  if (!raw) {
   753→    return ""
   754→  }
   755→
   756→  try {
   757→    return JSON.parse(`"${raw}"`)
   758→  } catch {
   759→    return raw
   760→      .replace(/\\n/g, "\n")
   761→      .replace(/\\r/g, "\r")
   762→      .replace(/\\t/g, "\t")
   763→      .replace(/\\"/g, "\"")
   764→      .replace(/\\\\/g, "\\")
   765→  }
   766→}
   767→
   768→function trySalvagePlannerDecision(text = "", availableTools = []) {
   769→  const raw = String(text || "").trim()
   770→  if (!raw) {
   771→    return null
   772→  }
   773→
   774→  const finalPrefix = "{\"type\":\"final\",\"content\":\""
   775→  if (raw.startsWith(finalPrefix)) {
   776→    return {
   777→      type: "final",
   778→      content: decodePlannerJsonStringFragment(raw.slice(finalPrefix.length))
   779→    }
   780→  }
   781→
   782→  const toolPrefix = "{\"type\":\"tool_use\",\"name\":\""
   783→  if (raw.startsWith(toolPrefix)) {
   784→    const toolNameEnd = raw.indexOf("\",\"arguments\":")
   785→    if (toolNameEnd <= toolPrefix.length) {
   786→      return null
   787→    }
   788→
   789→    const toolName = raw.slice(toolPrefix.length, toolNameEnd)
   790→    const available = new Set((availableTools || []).map(tool => String(tool?.name || "")))
   791→    if (!available.has(toolName)) {
   792→      return null
   793→    }
   794→
   795→    const argsStart = raw.indexOf("{", toolNameEnd)
   796→    if (argsStart < 0) {
   797→      return {
   798→        type: "tool_use",
   799→        name: toolName,
   800→        arguments: {},
   801→        prelude: ""
   802→      }
   803→    }
   804→
   805→    const preludeMarker = ",\"prelude\":\""
   806→    const preludeIndex = raw.indexOf(preludeMarker, argsStart)
   807→    const argsText =
   808→      preludeIndex >= 0
   809→        ? raw.slice(argsStart, preludeIndex)
   810→        : raw.slice(argsStart).replace(/}\s*$/, "}")
   811→
   812→    let parsedArgs = {}
   813→    try {
   814→      parsedArgs = JSON.parse(argsText.endsWith("}") ? argsText : `${argsText}}`)
   815→    } catch {
   816→      parsedArgs = {}
   817→    }
   818→
   819→    const prelude =
   820→      preludeIndex >= 0
   821→        ? decodePlannerJsonStringFragment(raw.slice(preludeIndex + preludeMarker.length))
   822→        : ""
   823→
   824→    return {
   825→      type: "tool_use",
   826→      name: toolName,
   827→      arguments: parsedArgs,
   828→      prelude
   829→    }
   830→  }
   831→
   832→  return null
   833→}
   834→
   835→function inferToolArgsFromNextStep(stepText = "", toolName = "") {
   836→  const raw = String(stepText || "").trim()
   837→  if (!raw || !toolName) {
