   839→  }
   840→
   841→  if (toolName === "mcp__cc-official-broker-runner__read_file") {
   842→    const readMatch = raw.match(/^Read\s+(.+?)\s+via\s+/i)
   843→    if (readMatch?.[1]) {
   844→      return { path: String(readMatch[1]).trim() }
   845→    }
   846→  }
   847→
   848→  if (toolName === "Read") {
   849→    const readMatch = raw.match(/^Read\s+(.+?)\s+via\s+/i)
   850→    if (readMatch?.[1]) {
   851→      return { file_path: String(readMatch[1]).trim() }
   852→    }
   853→  }
   854→
   855→  if (toolName === "Bash") {
   856→    const runMatch = raw.match(/^Run\s+(.+?)\s+via\s+/i)
   857→    if (runMatch?.[1]) {
