   865→function inferDecisionFromCcMeta(payload = {}, availableTools = []) {
   866→  const nextSteps = Array.isArray(payload?.cc_meta?.next_steps) ? payload.cc_meta.next_steps : []
   867→  if (!nextSteps.length) {
   868→    return null
   869→  }
   870→
   871→  const available = new Set((availableTools || []).map(tool => String(tool?.name || "")))
   872→  for (const step of nextSteps) {
   873→    const match = String(step || "").match(/\bvia\s+([A-Za-z0-9_:-]+)\s*$/i)
   874→    const toolName = String(match?.[1] || "")
   875→    if (!toolName || !available.has(toolName)) {
   876→      continue
   877→    }
   878→
   879→    const inferredArgs = inferToolArgsFromNextStep(step, toolName)
   880→    return {
   881→      type: "tool_use",
   882→      name: toolName,
   883→      arguments: inferredArgs || {},
   884→      prelude: ""
   885→    }
   886→  }
   887→
   888→  return null
   889→}
