   891→function parsePlannerDecision(payload = {}, availableTools = [], policy = {}) {
   892→  const blocks = extractResponsesBlocks(payload)
   893→  const text = blocks
   894→    .filter(block => block.type === "text")
   895→    .map(block => String(block.text || ""))
   896→    .join("\n")
   897→    .trim()
   898→
   899→  const parsed = tryParseJsonObject(text)
   900→  const available = new Set((availableTools || []).map(tool => String(tool?.name || "")))
   901→  const resolveAllowedToolName = rawName => {
   902→    const original = String(rawName || "")
   903→    if (!original) {
   904→      return ""
   905→    }
   906→    const mapped = mapMutatingBuiltinToRunner(original, availableTools)
   907→    if (available.has(original) || available.has(mapped)) {
   908→      return mapped
   909→    }
   910→    return ""
   911→  }
   912→
   913→  const finalizeDecision = decision => {
   914→    if (!decision || typeof decision !== "object") {
   915→      return decision
   916→    }
   917→
   918→    if (decision.type === "tool_use") {
   919→      const mappedName = mapMutatingBuiltinToRunner(decision.name, availableTools)
   920→      return {
   921→        ...decision,
   922→        name: mappedName
   923→      }
   924→    }
   925→
   926→    if (decision.type === "final" && policy?.requireToolDecision) {
   927→      throw new PlannerBoundaryError(
   928→        "remote planner returned final text for a turn that requires local write/bash/edit execution",
   929→        {
   930→          status: 409,
   931→          type: "invalid_request_error",
   932→          code: "planner_final_blocked_for_local_execution"
   933→        }
   934→      )
   935→    }
   936→
   937→    return decision
   938→  }
   939→
   940→  const parsedToolName = resolveAllowedToolName(parsed?.name)
   941→  if (parsed?.type === "tool_use" && parsedToolName) {
   942→    return finalizeDecision({
   943→      type: "tool_use",
   944→      name: parsedToolName,
   945→      arguments: parsed.arguments && typeof parsed.arguments === "object" ? parsed.arguments : {},
   946→      prelude: String(parsed.prelude || "").trim()
   947→    })
   948→  }
   949→
   950→  if (parsed?.type === "final") {
   951→    return finalizeDecision({
   952→      type: "final",
   953→      content: String(parsed.content || "").trim()
   954→    })
   955→  }
   956→
   957→  const salvaged = trySalvagePlannerDecision(text, availableTools)
   958→  const salvagedToolName = resolveAllowedToolName(salvaged?.name)
   959→  if (salvaged?.type === "tool_use" && salvagedToolName) {
   960→    return finalizeDecision({
   961→      type: "tool_use",
   962→      name: salvagedToolName,
   963→      arguments: salvaged.arguments && typeof salvaged.arguments === "object" ? salvaged.arguments : {},
   964→      prelude: String(salvaged.prelude || "").trim()
   965→    })
   966→  }
   967→
   968→  if (salvaged?.type === "final") {
   969→    return finalizeDecision({
   970→      type: "final",
   971→      content: String(salvaged.content || "").trim()
   972→    })
   973→  }
   974→
   975→  const inferred = inferDecisionFromCcMeta(payload, availableTools)
   976→  const inferredToolName = resolveAllowedToolName(inferred?.name)
   977→  if (inferred?.type === "tool_use" && inferredToolName) {
   978→    return finalizeDecision({
   979→      type: "tool_use",
   980→      name: inferredToolName,
   981→      arguments: inferred.arguments && typeof inferred.arguments === "object" ? inferred.arguments : {},
   982→      prelude: ""
   983→    })
   984→  }
   985→
   986→  if (policy?.requireToolDecision) {
   987→    throw new PlannerBoundaryError(
   988→      "remote planner did not return a valid tool_use/final decision JSON for a local execution turn",
   989→      {
   990→        status: 502,
   991→        type: "api_error",
   992→        code: "planner_invalid_decision_payload"
   993→      }
   994→    )
   995→  }
   996→
   997→  return finalizeDecision({
   998→    type: "final",
   999→    content: text
  1000→  })
  1001→}
