   468→function evaluateToolResultEvidence(messages = [], startIndex = -1, expectedToolNames = []) {
   469→  const list = Array.isArray(messages) ? messages : []
   470→  const expected = new Set((Array.isArray(expectedToolNames) ? expectedToolNames : []).map(name => String(name || "")).filter(Boolean))
   471→  const toolNameByUseId = buildToolNameByUseId(list)
   472→  let totalToolResults = 0
   473→  let matchedToolResults = 0
   474→  let unresolvedToolResults = 0
   475→
   476→  for (let messageIndex = Math.max(0, startIndex + 1); messageIndex < list.length; messageIndex += 1) {
   477→    const message = list[messageIndex] || {}
   478→    for (const block of normalizeMessageContent(message.content)) {
   479→      if (block?.type !== "tool_result") {
   480→        continue
   481→      }
   482→
   483→      totalToolResults += 1
   484→      const toolUseId = String(block.tool_use_id || "").trim()
   485→      const toolName = toolUseId ? toolNameByUseId.get(toolUseId) : ""
   486→      if (!toolName) {
   487→        unresolvedToolResults += 1
   488→        continue
   489→      }
   490→      if (expected.has(toolName)) {
   491→        matchedToolResults += 1
   492→      }
   493→    }
   494→  }
   495→
   496→  return {
   497→    totalToolResults,
   498→    matchedToolResults,
   499→    unresolvedToolResults
   500→  }
   501→}
   502→
   503→function hasSatisfiedLocalExecution(messages = [], latestUserAskIndex = -1, expectedToolNames = []) {
   504→  if (latestUserAskIndex < 0) {
   505→    return false
   506→  }
   507→
   508→  const evidence = evaluateToolResultEvidence(messages, latestUserAskIndex, expectedToolNames)
   509→  if (evidence.matchedToolResults > 0) {
   510→    return true
   511→  }
   512→
   513→  if (!evidence.totalToolResults) {
   514→    return false
   515→  }
   516→
   517→  return evidence.unresolvedToolResults > 0 && latestMessageIsToolResultOnly(messages)
   518→}
