   557→function buildPlannerPolicy(request = {}, availableTools = []) {
   558→  const messages = Array.isArray(request.messages) ? request.messages : []
   559→  const userAsk = extractUserAsk(request.messages || [])
   560→  const latestUserAskIndex = findLatestUserTextMessageIndex(messages)
   561→  const explicitToolName = normalizeToolChoiceName(normalizeToolChoice(request.tool_choice))
   562→  const availableNames = getAvailableToolNames(availableTools)
   563→  const requiredGroups = []
   564→
   565→  if (shouldRequireLocalFileMutationTool(userAsk, explicitToolName)) {
   566→    requiredGroups.push({
   567→      label: "local write/edit",
   568→      advertisedTools: [RUNNER_TOOL.writeFile, RUNNER_TOOL.applyPatch],
   569→      completionTools: [RUNNER_TOOL.writeFile, RUNNER_TOOL.applyPatch, "Write", "Edit"]
   570→    })
   571→  }
   572→
   573→  if (shouldRequireLocalBashTool(userAsk, explicitToolName)) {
   574→    requiredGroups.push({
   575→      label: "local bash",
   576→      advertisedTools: [RUNNER_TOOL.bash],
   577→      completionTools: [RUNNER_TOOL.bash, "Bash"]
   578→    })
   579→  }
   580→
   581→  const missingGroups = requiredGroups.filter(
   582→    group => !group.advertisedTools.some(toolName => availableNames.has(toolName))
   583→  )
   584→  const pendingGroups = requiredGroups.filter(
   585→    group => !hasSatisfiedLocalExecution(messages, latestUserAskIndex, group.completionTools)
   586→  )
   587→
   588→  return {
   589→    userAsk,
   590→    requireToolDecision: pendingGroups.length > 0,
   591→    requiredGroups,
   592→    pendingGroups,
   593→    missingGroups
   594→  }
   595→}
