   721→  const candidates = [raw]
   722→  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i)
   723→  if (fenced?.[1]) {
   724→    candidates.unshift(fenced[1].trim())
   725→  }
   726→
   727→  const firstBrace = raw.indexOf("{")
   728→  const lastBrace = raw.lastIndexOf("}")
   729→  if (firstBrace >= 0 && lastBrace > firstBrace) {
   730→    candidates.push(raw.slice(firstBrace, lastBrace + 1))
   731→  }
   732→
   733→  for (const candidate of candidates) {
   734→    try {
   735→      const parsed = JSON.parse(candidate)
   736→      if (parsed && typeof parsed === "object") {
   737→        return parsed
   738→      }
   739→    } catch {
   740→      // ignore
   741→    }
   742→  }
   743→
   744→  return null
   745→}
   746→
   747→function decodePlannerJsonStringFragment(fragment = "") {
   748→  const raw = String(fragment || "")
   749→    .replace(/"}?\s*$/, "")
   750→    .trim()
   751→
   752→  if (!raw) {
   753→    return ""
   754→  }
   755→
   756→  try {
   757→    return JSON.parse(`"${raw}"`)
   758→  } catch {
   759→    return raw
   760→      .replace(/\\n/g, "\n")
   761→      .replace(/\\r/g, "\r")
   762→      .replace(/\\t/g, "\t")
   763→      .replace(/\\"/g, "\"")
   764→      .replace(/\\\\/g, "\\")
   765→  }
   766→}
   767→
   768→function trySalvagePlannerDecision(text = "", availableTools = []) {
   769→  const raw = String(text || "").trim()
   770→  if (!raw) {
   771→    return null
   772→  }
   773→
   774→  const finalPrefix = "{\"type\":\"final\",\"content\":\""
   775→  if (raw.startsWith(finalPrefix)) {
   776→    return {
   777→      type: "final",
   778→      content: decodePlannerJsonStringFragment(raw.slice(finalPrefix.length))
   779→    }
   780→  }
   781→
   782→  const toolPrefix = "{\"type\":\"tool_use\",\"name\":\""
   783→  if (raw.startsWith(toolPrefix)) {
   784→    const toolNameEnd = raw.indexOf("\",\"arguments\":")
   785→    if (toolNameEnd <= toolPrefix.length) {
   786→      return null
   787→    }
   788→
   789→    const toolName = raw.slice(toolPrefix.length, toolNameEnd)
   790→    const available = new Set((availableTools || []).map(tool => String(tool?.name || "")))
   791→    if (!available.has(toolName)) {
   792→      return null
   793→    }
   794→
   795→    const argsStart = raw.indexOf("{", toolNameEnd)
   796→    if (argsStart < 0) {
   797→      return {
   798→        type: "tool_use",
   799→        name: toolName,
   800→        arguments: {},
   801→        prelude: ""
   802→      }
   803→    }
   804→
   805→    const preludeMarker = ",\"prelude\":\""
   806→    const preludeIndex = raw.indexOf(preludeMarker, argsStart)
   807→    const argsText =
   808→      preludeIndex >= 0
   809→        ? raw.slice(argsStart, preludeIndex)
   810→        : raw.slice(argsStart).replace(/}\s*$/, "}")
   811→
   812→    let parsedArgs = {}
   813→    try {
   814→      parsedArgs = JSON.parse(argsText.endsWith("}") ? argsText : `${argsText}}`)
   815→    } catch {
   816→      parsedArgs = {}
   817→    }
   818→
   819→    const prelude =
   820→      preludeIndex >= 0
   821→        ? decodePlannerJsonStringFragment(raw.slice(preludeIndex + preludeMarker.length))
   822→        : ""
   823→
   824→    return {
   825→      type: "tool_use",
   826→      name: toolName,
   827→      arguments: parsedArgs,
   828→      prelude
   829→    }
   830→  }
   831→
   832→  return null
   833→}
   834→
   835→function inferToolArgsFromNextStep(stepText = "", toolName = "") {
   836→  const raw = String(stepText || "").trim()
   837→  if (!raw || !toolName) {
   838→    return null
   839→  }
   840→
   841→  if (toolName === "mcp__cc-official-broker-runner__read_file") {
   842→    const readMatch = raw.match(/^Read\s+(.+?)\s+via\s+/i)
   843→    if (readMatch?.[1]) {
   844→      return { path: String(readMatch[1]).trim() }
   845→    }
   846→  }
   847→
   848→  if (toolName === "Read") {
   849→    const readMatch = raw.match(/^Read\s+(.+?)\s+via\s+/i)
   850→    if (readMatch?.[1]) {
   851→      return { file_path: String(readMatch[1]).trim() }
   852→    }
   853→  }
   854→
   855→  if (toolName === "Bash") {
   856→    const runMatch = raw.match(/^Run\s+(.+?)\s+via\s+/i)
   857→    if (runMatch?.[1]) {
   858→      return { command: String(runMatch[1]).trim() }
   859→    }
   860→  }
   861→
   862→  return null
   863→}
   864→
   865→function inferDecisionFromCcMeta(payload = {}, availableTools = []) {
   866→  const nextSteps = Array.isArray(payload?.cc_meta?.next_steps) ? payload.cc_meta.next_steps : []
   867→  if (!nextSteps.length) {
   868→    return null
   869→  }
   870→
   871→  const available = new Set((availableTools || []).map(tool => String(tool?.name || "")))
   872→  for (const step of nextSteps) {
   873→    const match = String(step || "").match(/\bvia\s+([A-Za-z0-9_:-]+)\s*$/i)
   874→    const toolName = String(match?.[1] || "")
   875→    if (!toolName || !available.has(toolName)) {
   876→      continue
   877→    }
   878→
   879→    const inferredArgs = inferToolArgsFromNextStep(step, toolName)
   880→    return {
   881→      type: "tool_use",
   882→      name: toolName,
   883→      arguments: inferredArgs || {},
   884→      prelude: ""
   885→    }
   886→  }
   887→
   888→  return null
   889→}
   890→
   891→function parsePlannerDecision(payload = {}, availableTools = [], policy = {}) {
   892→  const blocks = extractResponsesBlocks(payload)
   893→  const text = blocks
   894→    .filter(block => block.type === "text")
   895→    .map(block => String(block.text || ""))
   896→    .join("\n")
   897→    .trim()
   898→
   899→  const parsed = tryParseJsonObject(text)
   900→  const available = new Set((availableTools || []).map(tool => String(tool?.name || "")))
   901→  const resolveAllowedToolName = rawName => {
   902→    const original = String(rawName || "")
   903→    if (!original) {
   904→      return ""
   905→    }
   906→    const mapped = mapMutatingBuiltinToRunner(original, availableTools)
   907→    if (available.has(original) || available.has(mapped)) {
   908→      return mapped
   909→    }
   910→    return ""
   911→  }
   912→
   913→  const finalizeDecision = decision => {
   914→    if (!decision || typeof decision !== "object") {
   915→      return decision
   916→    }
   917→
   918→    if (decision.type === "tool_use") {
   919→      const mappedName = mapMutatingBuiltinToRunner(decision.name, availableTools)
   920→      return {
   921→        ...decision,
   922→        name: mappedName
   923→      }
   924→    }
   925→
   926→    if (decision.type === "final" && policy?.requireToolDecision) {
   927→      throw new PlannerBoundaryError(
   928→        "remote planner returned final text for a turn that requires local write/bash/edit execution",
   929→        {
   930→          status: 409,
   931→          type: "invalid_request_error",
   932→          code: "planner_final_blocked_for_local_execution"
   933→        }
   934→      )
   935→    }
   936→
   937→    return decision
   938→  }
   939→
   940→  const parsedToolName = resolveAllowedToolName(parsed?.name)
   941→  if (parsed?.type === "tool_use" && parsedToolName) {
   942→    return finalizeDecision({
   943→      type: "tool_use",
   944→      name: parsedToolName,
   945→      arguments: parsed.arguments && typeof parsed.arguments === "object" ? parsed.arguments : {},
   946→      prelude: String(parsed.prelude || "").trim()
   947→    })
   948→  }
   949→
   950→  if (parsed?.type === "final") {
   951→    return finalizeDecision({
   952→      type: "final",
   953→      content: String(parsed.content || "").trim()
   954→    })
   955→  }
   956→
   957→  const salvaged = trySalvagePlannerDecision(text, availableTools)
   958→  const salvagedToolName = resolveAllowedToolName(salvaged?.name)
   959→  if (salvaged?.type === "tool_use" && salvagedToolName) {
   960→    return finalizeDecision({
   961→      type: "tool_use",
   962→      name: salvagedToolName,
   963→      arguments: salvaged.arguments && typeof salvaged.arguments === "object" ? salvaged.arguments : {},
   964→      prelude: String(salvaged.prelude || "").trim()
   965→    })
   966→  }
   967→
   968→  if (salvaged?.type === "final") {
   969→    return finalizeDecision({
   970→      type: "final",
   971→      content: String(salvaged.content || "").trim()
   972→    })
   973→  }
   974→
   975→  const inferred = inferDecisionFromCcMeta(payload, availableTools)
   976→  const inferredToolName = resolveAllowedToolName(inferred?.name)
   977→  if (inferred?.type === "tool_use" && inferredToolName) {
   978→    return finalizeDecision({
   979→      type: "tool_use",
   980→      name: inferredToolName,
   981→      arguments: inferred.arguments && typeof inferred.arguments === "object" ? inferred.arguments : {},
   982→      prelude: ""
   983→    })
   984→  }
   985→
   986→  if (policy?.requireToolDecision) {
   987→    throw new PlannerBoundaryError(
   988→      "remote planner did not return a valid tool_use/final decision JSON for a local execution turn",
   989→      {
   990→        status: 502,
   991→        type: "api_error",
   992→        code: "planner_invalid_decision_payload"
   993→      }
   994→    )
   995→  }
   996→
   997→  return finalizeDecision({
   998→    type: "final",
   999→    content: text
  1000→  })
  1001→}
