  1024→function anthropicMessagesToResponsesInput(messages = []) {
  1025→  const items = []
  1026→
  1027→  for (const message of messages) {
  1028→    const role = String(message?.role || "user")
  1029→    const textParts = []
  1030→
  1031→    const flushTextParts = currentRole => {
  1032→      if (!textParts.length) return
  1033→      items.push({
  1034→        type: "message",
  1035→        role: currentRole,
  1036→        content: [...textParts]
  1037→      })
  1038→      textParts.length = 0
  1039→    }
  1040→
  1041→    for (const block of normalizeMessageContent(message?.content)) {
  1042→      const blockType = block.type
  1043→      if (blockType === "text" || blockType === "image") {
  1044→        const converted = contentBlockToResponses(block, role)
  1045→        if (converted) {
  1046→          textParts.push(converted)
  1047→        }
  1048→        continue
  1049→      }
  1050→
  1051→      if (blockType === "tool_use") {
  1052→        flushTextParts(role)
  1053→        items.push({
  1054→          type: "function_call",
  1055→          call_id: String(block.id || ""),
  1056→          name: String(block.name || ""),
  1057→          arguments: JSON.stringify(block.input || {})
  1058→        })
  1059→        continue
  1060→      }
  1061→
  1062→      if (blockType === "tool_result") {
  1063→        flushTextParts(role)
  1064→        items.push({
  1065→          type: "function_call_output",
  1066→          call_id: String(block.tool_use_id || ""),
  1067→          output: toolResultText(block.content)
  1068→        })
  1069→      }
  1070→    }
  1071→
  1072→    flushTextParts(role)
  1073→  }
  1074→
  1075→  return items
  1076→}
