  1111→function approxTokenCount(payload = {}) {
  1112→  const parts = []
  1113→  const system = systemToInstructions(payload.system)
  1114→  if (system) {
  1115→    parts.push(system)
  1116→  }
  1117→
  1118→  for (const message of payload.messages || []) {
  1119→    for (const block of normalizeMessageContent(message?.content)) {
  1120→      if (block.type === "text") {
  1121→        parts.push(String(block.text || ""))
  1122→      } else if (block.type === "tool_use") {
  1123→        parts.push(JSON.stringify(block.input || {}))
  1124→      } else if (block.type === "tool_result") {
  1125→        parts.push(toolResultText(block.content))
  1126→      }
  1127→    }
  1128→  }
  1129→
  1130→  const combined = parts.join("\n")
  1131→  return Math.max(1, Math.ceil(combined.length / 4))
  1132→}
