  1219→    }
  1220→    blocks.push({
  1221→      type: "tool_use",
  1222→      id: String(toolCall.id || `toolu_${randomUUID().replace(/-/g, "")}`),
  1223→      name: String(fn.name || ""),
  1224→      input: parsedInput
  1225→    })
  1226→  }
