   263→    let result = (existingConfig && config.advanced?.preserveExistingDomains) ? clone(existingConfig) : {}
   264→    let toProcess = targetDomains ? new Set(targetDomains) : new Set([...Object.keys(domains), ...Object.keys(adsData)])
   265→
   266→    // 跨域名重复性校验存储
   267→    const uniqueStore = { firebase: new Map(), siteName: new Map(), iamemail: new Map() }
   268→
   269→    for (const domain of toProcess) {
   270→        const domainData = domains[domain] || null; const ads = adsData[domain] || null
   271→        if (!domainData && !ads) continue
   272→        const existing = result[domain] || null
   273→        let final;
   274→        if (adsOnly && existing) {
   275→            const type = ads.type || config.advanced?.defaultAdsType || 'adx'
   276→            const adsense = type === 'adsense' ? generateAdsenseConfig(ads, config, adsTemplate) : generateAdxConfig(ads, config, adsTemplate)
   277→            final = { ...existing, adsense: deepMerge(existing.adsense || {}, adsense) }
   278→        } else {
   279→            final = generateDomainConfig(domain, domainData, ads, config, existing, adsTemplate)
   280→        }
   281→        result[domain] = final
   282→
   283→        // --- 深度重复校验 ---
   284→        const checkDuplicate = (data, label) => {
   285→            if (!data) return
   286→            const key = String(label || '').toLowerCase()
   287→            if (!uniqueStore[key]) return
   288→            const strValue = (typeof data === 'object') ? stableStringify(data) : String(data).trim()
   289→            if (strValue.length < 10) return // 忽略太短的值
   290→            if (uniqueStore[key].has(strValue)) {
   291→                console.log(`\n\x1b[43m\x1b[30m[重复报警]\x1b[0m 域名 "${domain}" 的 ${label} 数据与 "${uniqueStore[key].get(strValue)}" 完全一致！请检查 Excel 是否公式拉错。`)
   292→            } else {
   293→                uniqueStore[key].set(strValue, domain)
   294→            }
   295→        }
   296→        if (!adsOnly) {
   297→            checkDuplicate(final.firebase, 'Firebase')
   298→            checkDuplicate(final.siteName, 'siteName')
   299→            checkDuplicate(final.IAMEMAIL, 'IAMEMAIL')
   300→        }
   301→    }
   302→    return result
   303→}
